package appcatalog

import (
	"embed"
	"encoding/json"
	"fmt"
	"log/slog"
	"net/url"
	"sort"
	"strings"
	"sync"
)

// Layer 2 of recognition: the table generated by cmd/appcatalog-sync from the
// Coolify service templates (Apache-2.0) and the Dokploy templates (MIT), and
// the hand overrides applied on top of it. The hand entries in catalog.go win
// over the table; overrides.json wins over both for presentation, so a logo
// can be replaced or removed without regenerating anything.

//go:embed generated/catalog.json generated/fingerprints.json generated/icons.json overrides.json
var generatedFiles embed.FS

// Evidence values: which recognition layer named the application.
const (
	EvidenceLabel           = "label"
	EvidenceImage           = "image"
	EvidenceName            = "name"
	EvidenceHTTPFingerprint = "http_fingerprint"
	EvidenceReleasedCatalog = "released_catalog"

	logoRemoved       = "removed"
	defaultCategory   = "other"
	simpleIconsPrefix = "si:"
	minNameMatchID    = 5
)

type generatedSource struct {
	ID         string `json:"id"`
	Repository string `json:"repository"`
	Commit     string `json:"commit"`
	License    string `json:"license"`
	Path       string `json:"path,omitempty"`
}

type generatedApp struct {
	ID         string   `json:"id"`
	Name       string   `json:"name"`
	Category   string   `json:"category"`
	Homepage   string   `json:"homepage"`
	SourceRepo string   `json:"source_repo"`
	WebPort    int      `json:"web_port"`
	WebScheme  string   `json:"web_scheme"`
	Images     []string `json:"images"`
	Icon       string   `json:"icon"`
}

type generatedCatalog struct {
	Schema  string            `json:"schema"`
	Sources []generatedSource `json:"sources"`
	Apps    []generatedApp    `json:"apps"`
}

type iconAsset struct {
	Source  string   `json:"source"`
	Formats []string `json:"formats"`
	Light   string   `json:"light,omitempty"`
	Dark    string   `json:"dark,omitempty"`
	Hex     string   `json:"hex,omitempty"`
}

type iconIndex struct {
	Schema  string               `json:"schema"`
	BaseURL string               `json:"base_url"`
	Sources []generatedSource    `json:"sources"`
	Icons   map[string]iconAsset `json:"icons"`
}

type appOverride struct {
	Name          string   `json:"name"`
	Category      string   `json:"category"`
	Homepage      string   `json:"homepage"`
	WebPort       int      `json:"web_port"`
	WebScheme     string   `json:"web_scheme"`
	Icon          string   `json:"icon"`
	Logo          string   `json:"logo"`
	Images        []string `json:"images"`
	ExcludeImages []string `json:"exclude_images"`
	Exclude       bool     `json:"exclude"`
}

type overridesFile struct {
	Schema             string                 `json:"schema"`
	Apps               map[string]appOverride `json:"apps"`
	Icons              map[string]iconAsset   `json:"icons"`
	FingerprintAliases map[string]string      `json:"fingerprint_aliases"`
	GenericImages      []string               `json:"generic_images"`
}

// generatedTable is the loaded layer-2 data and its lookup indexes.
type generatedTable struct {
	apps      map[string]*generatedApp
	byImage   map[string]string
	bySource  map[string]string
	nameIDs   []string
	icons     map[string]iconAsset
	iconBase  string
	overrides map[string]appOverride
	sources   []generatedSource
}

// nameMatchStopwords are generated ids too generic to recognize a container by
// its name alone; such an application is still recognized by its image.
var nameMatchStopwords = map[string]bool{
	"admin": true, "agent": true, "backend": true, "cache": true, "client": true, "database": true,
	"dashboard": true, "docker": true, "files": true, "frontend": true, "media": true, "monitor": true,
	"panel": true, "proxy": true, "queue": true, "server": true, "service": true, "static": true,
	"storage": true, "worker": true,
}

var loadGeneratedTable = sync.OnceValue(func() *generatedTable {
	table, err := parseGeneratedTable()
	if err != nil {
		// The embedded files are produced and validated by cmd/appcatalog-sync;
		// a broken table degrades recognition to the hand catalog, it never
		// stops the agent or the control plane.
		slog.Error("generated application catalog is invalid", "error", err)
		return &generatedTable{apps: map[string]*generatedApp{}, icons: map[string]iconAsset{}, iconBase: defaultIconBaseURL}
	}
	return table
})

func parseGeneratedTable() (*generatedTable, error) {
	var catalog generatedCatalog
	var icons iconIndex
	var overrides overridesFile
	for name, target := range map[string]any{
		"generated/catalog.json": &catalog, "generated/icons.json": &icons, "overrides.json": &overrides,
	} {
		raw, err := generatedFiles.ReadFile(name)
		if err != nil {
			return nil, err
		}
		if err := json.Unmarshal(raw, target); err != nil {
			return nil, fmt.Errorf("%s: %w", name, err)
		}
	}
	table := &generatedTable{
		apps: map[string]*generatedApp{}, byImage: map[string]string{}, bySource: map[string]string{},
		icons: map[string]iconAsset{}, iconBase: strings.TrimSpace(icons.BaseURL), overrides: overrides.Apps,
		sources: append(append([]generatedSource(nil), catalog.Sources...), icons.Sources...),
	}
	if table.iconBase == "" {
		table.iconBase = defaultIconBaseURL
	}
	for slug, asset := range icons.Icons {
		table.icons[slug] = asset
	}
	for slug, asset := range overrides.Icons {
		table.icons[slug] = asset
	}
	for index := range catalog.Apps {
		app := &catalog.Apps[index]
		override, overridden := overrides.Apps[app.ID]
		if overridden && override.Exclude {
			continue
		}
		applyAppOverride(app, override)
		table.apps[app.ID] = app
		for _, image := range app.Images {
			table.byImage[normalizeImagePath(image)] = app.ID
		}
		if repo := strings.ToLower(strings.TrimSpace(app.SourceRepo)); repo != "" {
			table.bySource[repo] = app.ID
		}
		if len(app.Images) > 0 && !nameMatchStopwords[app.ID] && (len(app.ID) >= minNameMatchID || strings.Contains(app.ID, "-")) {
			table.nameIDs = append(table.nameIDs, app.ID)
		}
	}
	sort.Strings(table.nameIDs)
	return table, nil
}

func applyAppOverride(app *generatedApp, override appOverride) {
	if override.Name != "" {
		app.Name = override.Name
	}
	if override.Category != "" {
		app.Category = override.Category
	}
	if override.Homepage != "" {
		app.Homepage = override.Homepage
	}
	if override.WebPort > 0 {
		app.WebPort, app.WebScheme = override.WebPort, override.WebScheme
	}
	if override.Icon != "" {
		app.Icon = override.Icon
	}
	excluded := map[string]bool{}
	for _, image := range override.ExcludeImages {
		excluded[normalizeImagePath(image)] = true
	}
	images := make([]string, 0, len(app.Images)+len(override.Images))
	for _, image := range append(append([]string(nil), app.Images...), override.Images...) {
		if image = normalizeImagePath(image); image != "" && !excluded[image] {
			images = append(images, image)
		}
	}
	app.Images = images
}

// normalizeImagePath reduces an image reference or repository to the path the
// generated table is keyed by: no registry, tag or digest, no "library/".
func normalizeImagePath(image string) string {
	image = strings.ToLower(strings.TrimSpace(image))
	if image == "" {
		return ""
	}
	if repo := ParseImage(image).Repo; repo != "" {
		image = repo
	}
	return strings.TrimPrefix(image, "library/")
}

func generatedByImage(repo string) *Entry {
	table := loadGeneratedTable()
	return table.entry(table.byImage[normalizeImagePath(repo)])
}

func generatedBySourceRepo(repo string) *Entry {
	if repo == "" {
		return nil
	}
	table := loadGeneratedTable()
	if id, ok := table.bySource[repo]; ok {
		return table.entry(id)
	}
	// LinuxServer's "docker-<app>" repositories package the upstream app.
	if owner, name, _ := strings.Cut(repo, "/"); owner == "linuxserver" && strings.HasPrefix(name, "docker-") {
		return lookupKnown(strings.TrimPrefix(name, "docker-"), false)
	}
	return nil
}

// generatedByName recognizes a unit whose name contains a generated
// application id as a whole token run (`media-sonarr-1`). Short and generic
// ids are excluded; see nameMatchStopwords.
func generatedByName(tokens []string) *Entry {
	table := loadGeneratedTable()
	best, bestScore := "", 0
	for _, id := range table.nameIDs {
		pattern := tokenize(id)
		if containsTokens(tokens, pattern) && len(pattern) > bestScore {
			best, bestScore = id, len(pattern)
		}
	}
	return table.entry(best)
}

func (t *generatedTable) entry(id string) *Entry {
	app, ok := t.apps[id]
	if !ok {
		return nil
	}
	entry := &Entry{
		ID: app.ID, DisplayName: firstNonEmpty(app.Name, app.ID), Category: firstNonEmpty(app.Category, defaultCategory),
		BrandDomain: homepageDomain(app.Homepage), WebPort: app.WebPort, HomepageURL: app.Homepage,
		webScheme: app.WebScheme, icon: app.Icon,
	}
	attachPresentation(entry)
	return entry
}

// lookupKnown resolves an application id from the hand and released catalogs
// (by id, then by an exact hand name such as "pihole") and the generated
// table. iconOnly also accepts a mirrored dashboard icon of that name; only
// evidence an operator chose on purpose (a dashboard label, a fingerprint
// mapped by the generator) may name an application that way, never an image
// title a base image or packager set.
func lookupKnown(id string, iconOnly bool) *Entry {
	id = slugify(id)
	if id == "" {
		return nil
	}
	if entry := Lookup(id); entry != nil {
		return entry
	}
	if entry := exactHandName(id); entry != nil {
		return entry
	}
	table := loadGeneratedTable()
	if entry := table.entry(id); entry != nil {
		return entry
	}
	if asset, ok := table.icons[id]; iconOnly && ok && asset.Source == iconSourceDashboardIcons {
		entry := &Entry{ID: id, DisplayName: titleFromSlug(id), Category: defaultCategory}
		attachPresentation(entry)
		return entry
	}
	return nil
}

// exactHandName finds the hand entry one of whose name patterns is exactly id.
func exactHandName(id string) *Entry {
	for index := range entries {
		for _, name := range entries[index].names {
			if slugify(name) == id {
				return copyEntry(&entries[index])
			}
		}
	}
	return nil
}

// attachPresentation completes an entry from the generated table and the hand
// overrides: the project homepage, the default web port, and the logo.
func attachPresentation(entry *Entry) {
	table := loadGeneratedTable()
	if app, ok := table.apps[entry.ID]; ok {
		if entry.HomepageURL == "" {
			entry.HomepageURL = app.Homepage
		}
		if entry.BrandDomain == "" {
			entry.BrandDomain = homepageDomain(app.Homepage)
		}
		if entry.WebPort == 0 && app.WebPort > 0 {
			entry.WebPort, entry.webScheme = app.WebPort, app.WebScheme
		}
		if entry.icon == "" {
			entry.icon = app.Icon
		}
	}
	override := table.overrides[entry.ID]
	if override.Homepage != "" {
		entry.HomepageURL = override.Homepage
	}
	if override.WebPort > 0 {
		entry.WebPort, entry.webScheme = override.WebPort, override.WebScheme
	}
	if override.Icon != "" {
		entry.icon = override.Icon
	}
	if override.Logo == logoRemoved {
		entry.Logo, entry.IconURL, entry.LogoRemoved = nil, genericIconURL(table), true
		return
	}
	entry.Logo = table.logo(entry.iconSlug())
	entry.IconURL = table.rasterURL(entry.iconSlug())
}

// iconSlug is the icon this entry is drawn with: its own reference, else its
// id. PostgreSQL's dashboard icon is named after the project, not the image.
func (e *Entry) iconSlug() string {
	if e.icon != "" {
		return e.icon
	}
	if e.ID == "postgres" {
		return "postgresql"
	}
	return e.ID
}

func homepageDomain(homepage string) string {
	parsed, err := url.Parse(strings.TrimSpace(homepage))
	if err != nil || parsed.Hostname() == "" || parsed.Hostname() == "github.com" {
		return ""
	}
	return strings.TrimPrefix(strings.ToLower(parsed.Hostname()), "www.")
}

func titleFromSlug(slug string) string {
	words := strings.Split(slug, "-")
	for index, word := range words {
		if word != "" {
			words[index] = strings.ToUpper(word[:1]) + word[1:]
		}
	}
	return strings.Join(words, " ")
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

// Source is one upstream dataset recognition is generated from.
type Source struct {
	ID         string `json:"id"`
	Repository string `json:"repository"`
	Commit     string `json:"commit"`
	License    string `json:"license"`
}

// Sources lists the upstream datasets of the generated table, fingerprints
// and icons with their licences, for the credits page.
func Sources() []Source {
	table := loadGeneratedTable()
	fingerprints := loadFingerprints()
	all := append(append([]generatedSource(nil), table.sources...), fingerprints.sources...)
	result := make([]Source, 0, len(all))
	seen := map[string]bool{}
	for _, source := range all {
		if source.ID == "" || seen[source.ID] {
			continue
		}
		seen[source.ID] = true
		result = append(result, Source{ID: source.ID, Repository: source.Repository, Commit: source.Commit, License: source.License})
	}
	sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
	return result
}
